--
-- 테이블 구조 `invoices`
--

CREATE TABLE `invoices` (
  `id` int(11) NOT NULL,
  `restaurant_id` int(11) NOT NULL,
  `invoice_number` varchar(255) NOT NULL,
  `type` enum('automatic','manual') DEFAULT 'manual',
  `billing_period_start` datetime NOT NULL,
  `billing_period_end` datetime NOT NULL,
  `due_date` datetime NOT NULL,
  `total_amount` decimal(10,2) NOT NULL,
  `paid_amount` decimal(10,2) DEFAULT 0.00,
  `status` enum('draft','pending_payment','payment_submitted','paid','overdue','cancelled') DEFAULT 'draft',
  `notes` text DEFAULT NULL,
  `issued_by` int(11) NOT NULL,
  `issued_at` datetime DEFAULT NULL,
  `paid_at` datetime DEFAULT NULL,
  `payment_method` varchar(50) DEFAULT NULL,
  `transaction_id` varchar(255) DEFAULT NULL,
  `payment_notes` text DEFAULT NULL,
  `receipt_url` varchar(500) DEFAULT NULL,
  `payer_type` enum('restaurant','foodcourt_manager','brand_manager') DEFAULT 'restaurant' COMMENT 'Who is responsible for payment',
  `payer_id` int(11) DEFAULT NULL COMMENT 'ID of the payer (manager_id if payer_type is manager)',
  `invoice_category` enum('subscription','service','consulting','others') DEFAULT 'subscription' COMMENT 'Invoice category type',
  `custom_description` varchar(255) DEFAULT NULL COMMENT 'Custom description for others category',
  `service_description` text DEFAULT NULL COMMENT 'Detailed service or consulting description',
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

