--
-- 테이블 구조 `plan_templates`
--

CREATE TABLE `plan_templates` (
  `id` int(11) NOT NULL,
  `name` varchar(100) NOT NULL,
  `display_name` varchar(100) NOT NULL,
  `base_price_monthly` decimal(10,2) NOT NULL,
  `base_price_annual` decimal(10,2) NOT NULL,
  `order_limit` int(11) NOT NULL DEFAULT 1000 COMMENT '-1 for unlimited',
  `menu_item_limit` int(11) NOT NULL DEFAULT 50 COMMENT '-1 for unlimited',
  `staff_limit` int(11) NOT NULL DEFAULT 5 COMMENT '-1 for unlimited',
  `category` enum('basic','custom') NOT NULL DEFAULT 'basic' COMMENT 'Plan category: basic for standard plans, custom for custom plans',
  `features` text DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT 1,
  `sort_order` int(11) DEFAULT 0,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

--
-- 테이블의 덤프 데이터 `plan_templates`
--

INSERT INTO `plan_templates` (`id`, `name`, `display_name`, `base_price_monthly`, `base_price_annual`, `order_limit`, `menu_item_limit`, `staff_limit`, `category`, `features`, `is_active`, `sort_order`, `createdAt`, `updatedAt`) VALUES
