(3, 'enterprise', 'Enterprise Plan', 99.00, 990.00, -1, -1, -1, 'basic', '\"[\\\"Full POS Suite\\\",\\\"Custom Integrations\\\",\\\"Premium Support\\\",\\\"Analytics Dashboard\\\"]\"', 1, 3, '2025-11-02 10:34:24', '2025-11-02 10:34:24');

