--
-- 테이블 구조 `restaurants`
--

CREATE TABLE `restaurants` (
  `id` int(11) NOT NULL,
  `name` varchar(255) NOT NULL,
  `slug` varchar(255) DEFAULT NULL COMMENT 'URL-friendly restaurant identifier',
  `manager_id` int(11) DEFAULT NULL,
  `manager_name` varchar(255) DEFAULT NULL,
  `email` varchar(100) DEFAULT NULL,
  `phone` varchar(20) DEFAULT NULL,
  `address` text DEFAULT NULL,
  `city` varchar(100) DEFAULT NULL,
  `state` varchar(100) DEFAULT NULL,
  `postal_code` varchar(20) DEFAULT NULL,
  `country` varchar(100) DEFAULT 'Malaysia',
  `business_registration` varchar(100) DEFAULT NULL COMMENT 'Business registration number',
  `trade_name` varchar(255) DEFAULT NULL COMMENT 'Trading name or brand name',
  `tax_id` varchar(100) DEFAULT NULL COMMENT 'Tax identification number (SST/GST)',
  `website` varchar(255) DEFAULT NULL,
  `bank_name` varchar(255) DEFAULT NULL,
  `bank_account` varchar(100) DEFAULT NULL,
  `bank_account_name` varchar(255) DEFAULT NULL,
  `logo_url` text DEFAULT NULL COMMENT 'URL or base64 encoded logo image',
  `plan_type` enum('Basic Plan','Professional Plan','Enterprise Plan') DEFAULT 'Basic Plan',
  `plan_amount` decimal(10,2) DEFAULT 29.00,
  `billing_cycle` enum('monthly','annual') DEFAULT 'monthly',
  `status` enum('active','inactive') DEFAULT 'active',
  `subscription_start` datetime DEFAULT NULL,
  `subscription_end` datetime DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `subscription_snapshot` text DEFAULT NULL COMMENT 'JSON snapshot of plan details at subscription time',
  `order_limit` int(11) DEFAULT 1000 COMMENT 'Monthly order limit from subscription plan',
  `menu_item_limit` int(11) DEFAULT 50 COMMENT 'Menu item limit from subscription plan',
  `staff_limit` int(11) DEFAULT 5 COMMENT 'Staff account limit from subscription plan',
  `payment_settings` mediumtext DEFAULT NULL COMMENT 'JSON settings for payment methods',
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `operation_settings` text DEFAULT NULL COMMENT 'JSON settings for restaurant operations (timezone, opening hours, etc.)'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

--
