--
-- 테이블 구조 `restaurant_customers`
--

CREATE TABLE `restaurant_customers` (
  `id` int(11) NOT NULL,
  `restaurant_id` int(11) NOT NULL COMMENT '레스토랑 ID',
  `customer_id` int(11) NOT NULL COMMENT '고객 ID',
  `points` int(11) DEFAULT 0 COMMENT '레스토랑별 포인트',
  `total_orders` int(11) DEFAULT 0 COMMENT '레스토랑별 총 주문 횟수',
  `total_spent` decimal(10,2) DEFAULT 0.00 COMMENT '레스토랑별 총 지출 금액',
  `loyalty_tier` enum('Bronze','Silver','Gold','VIP') DEFAULT 'Bronze' COMMENT '로열티 등급',
  `first_order_at` datetime DEFAULT NULL COMMENT '첫 주문 일시',
  `last_order_at` datetime DEFAULT NULL COMMENT '마지막 주문 일시',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

-- --------------------------------------------------------

--
-- 테이블 구조 `restaurant_managers`
--

CREATE TABLE `restaurant_managers` (
  `id` int(11) NOT NULL,
  `restaurant_id` int(11) NOT NULL,
  `manager_id` int(11) NOT NULL,
  `is_primary` tinyint(1) DEFAULT 0 COMMENT 'Indicates if this is the primary manager for backward compatibility',
  `assigned_at` datetime DEFAULT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

