--
-- 테이블 구조 `support_tickets`
--

CREATE TABLE `support_tickets` (
  `id` varchar(255) NOT NULL,
  `ticketNumber` varchar(255) NOT NULL,
  `customerId` varchar(255) NOT NULL,
  `customerName` varchar(255) NOT NULL,
  `customerEmail` varchar(255) NOT NULL,
  `customerRole` varchar(255) DEFAULT 'restaurant',
  `restaurantId` int(11) DEFAULT NULL,
  `restaurantName` varchar(255) DEFAULT NULL,
  `subject` varchar(255) NOT NULL,
  `description` text NOT NULL,
  `status` enum('open','in-progress','resolved','closed') DEFAULT 'open',
  `priority` enum('low','medium','high','urgent') DEFAULT 'medium',
  `category` enum('general','technical','billing','feature-request','bug-report') DEFAULT 'general',
  `assignedTo` varchar(255) DEFAULT NULL,
  `response` text DEFAULT NULL,
  `responseTime` int(11) DEFAULT 0 COMMENT 'Response time in minutes',
  `resolutionTime` int(11) DEFAULT NULL COMMENT 'Resolution time in minutes',
  `resolvedAt` datetime DEFAULT NULL,
  `replyMessage` text DEFAULT NULL,
  `repliedBy` varchar(255) DEFAULT NULL,
  `repliedAt` datetime DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

--
-- 테이블의 덤프 데이터 `support_tickets`
--

